face(74.25, false); face(222.75, true);
d.setDrawColor(170); d.setLineDashPattern([3, 2], 0); d.line(148.5, 8, 148.5, 202);
d.save(`wifi-tent-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}.pdf`);
